 # Actual publication external catalog; full/coast may inline, so only parse known current external form.
 if dist=='dist-publish':
  js=[x for x in h.scripts if re.fullmatch('/assets/journey-data-[0-9a-f]+.js',x)];assert len(js)==1;jf=R/'projects/site'/dist/js[0].lstrip('/');txt=jf.read_text();prefix="document.getElementById('journey-data').textContent=";assert txt.startswith(prefix);catalog=json.loads(json.loads(txt[len(prefix):].strip().removesuffix(';')));item=next(x for x in catalog['catalog'] if x['id']==story['save_id']);save('portable-reading-observation.json',{'artifact':str(jf.relative_to(R)),'sha256':sha(jf),'item':item,'limits':'Cached build observation, not browser Save/download test or live-site assertion.'})
save('rendered-route-observations.json',{'status':'PASS_CACHED_ARTIFACT_INSPECTION','editions':render,'coast_allowed_links':{('/food/'+s+'/'):('/food/'+s+'/') in coast['routes'] for s in slugs},'connection_allowed':{x['href']:x['href'] in coast['routes'] for x in story['connections']},'limits':'No new build or network; generated artifacts may be stale relative to a future candidate. Current source/template corroborates observed structure.'})
paths=['kb/research/food/everyday-stories.json','kb/research/food/collection.json','kb/research/food/everyday-food-culture.md','projects/site/src/pages/food/everyday.astro','projects/site/src/components/FoodStoryCollection.astro','projects/site/src/components/MagazineCover.astro','projects/site/src/components/SaveJourney.astro','projects/site/src/data/edition.ts','projects/site/src/data/journey-catalog.ts','projects/site/editions/coast.json','kb/reference/article-editorial-standard.md','kb/research/methods/research-map.md']+[f'kb/research/food/{s}.md' for s in slugs]
